  (() => {
    const selection = $('Wait2').item.json['Slot booking'];
    const timeMatch = selection.match(/(\d{1,2}):(\d{2})\s*(AM|PM)/i);
    const dateMatch = selection.match(/(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s*(\d{1,2})/i);
    if (!timeMatch || !dateMatch) return null;

    let [_, hours, minutes, modifier] = timeMatch;
    hours = parseInt(hours, 10);
    if (modifier.toUpperCase() === 'PM' && hours < 12) hours += 12;
    if (modifier.toUpperCase() === 'AM' && hours === 12) hours = 0;

    const months = { Jan:'01', Feb:'02', Mar:'03', Apr:'04', May:'05', Jun:'06', Jul:'07', Aug:'08', Sep:'09', Oct:'10', Nov:'11', Dec:'12' };
    const month = months[dateMatch[1]];
    const day = dateMatch[2].padStart(2, '0');
    const year = $('Wait2').item.json['submittedAt'] ? $('Wait2').item.json['submittedAt'].substring(0, 4) : "2026"; 

    const pad = (num) => String(num).padStart(2, '0');

    // Crucial Change: Appended '+05:30' directly to lock it to India Time
    return `${year}-${month}-${day}T${pad(hours)}:${pad(minutes)}:00+05:30`;
  })()
}}

